def _tdx_ema(series, n):
    """通达信 EMA(X,N) 口径，等价 SMA(X, N+1, 2)。

    递推式 Y=(X*2+Y'*(N-1))/(N+1)，前 N+1 项均值做种子。
    pandas 的 ewm(adjust=False) 以首元素做种子，两者在序列前段有差异。
    """
    values = list(series)
    if len(values) < n:
        return pd.Series([float("nan")] * len(values), index=series.index)
    span = n + 1
    prev = sum(values[:span]) / span
    out_v = []
    for x in values:
        prev = (x * 2 + prev * (n - 1)) / (n + 1)
        out_v.append(prev)
    return pd.Series(out_v, index=series.index)


def _wilder_series(series, n=14):
    """TDX Wilder smoothing, equivalent to SMA(X, N, 1): Y=(X+Y'*(N-1))/N.

    The seed is the mean of the first n non-NaN values, so this is safe to use on
    the output of closes.diff() whose first element is NaN. The trailing value is
    NaN when there are fewer than n usable values.
    """
    values = [v for v in series if pd.notna(v)]
    if len(values) < n:
        return pd.Series([float('nan')] * len(series), index=series.index)
    prev = sum(values[:n]) / n
    out_v = []
    for x in values:
        prev = (x + prev * (n - 1)) / n
        out_v.append(prev)
    return pd.Series(out_v, index=series.index[-len(out_v):])


def _pin_shape(o, h, l, c):
    """单根K线的插针形态：长影线 + 短实体（判定口径见 technical_indicators._bar_shape）。

    两处指标实现必须给出一致的结论，否则同一根K线在日报里会出现两种说法
    （52.7 节记过这个教训：MACD/RSI 曾经各写一份、口径漂移）。
    """
    span = h - l
    if span <= 0:
        return None
    body = abs(c - o)
    upper = h - max(o, c)
    lower = min(o, c) - l
    kind, shadow = ("upper", upper) if upper >= lower else ("lower", lower)
    body_ratio = body / span
    shadow_ratio = shadow / span
    if body_ratio > 1.0 / 3.0 or shadow_ratio < 0.5:
        return None
    if body > 0 and shadow < body * 2:
        return None
    return kind


def detect_pins(df: pd.DataFrame, lookback: int = 20) -> List[str]:
    """最近 lookback 根K线里的插针方向，最新在前，形如 ["lower", "upper"]。

    只做形状判定，不加 ATR 过滤：这里的调用方是日报文本，缺 ATR 上下文，
    而形状判定已经足够保守（实体必须不足振幅三分之一）。
    """
    if df.empty or len(df) < 1:
        return []
    need = {"开盘", "最高", "最低", "收盘"}
    if not need.issubset(df.columns):
        return []
    window = df.iloc[-lookback:] if lookback > 0 else df
    pins = []
    for _, row in window.iloc[::-1].iterrows():
        kind = _pin_shape(row["开盘"], row["最高"], row["最低"], row["收盘"])
        if kind:
            pins.append(kind)
    return pins

def calculate_technical(df: pd.DataFrame) -> Dict:
    """计算技术指标（MA/RSI/MACD/布林带）"""
    if df.empty or len(df) < 20:
        return {}
    
    closes = df["收盘"]
    
    # 简单均线
    ma5 = closes.rolling(5).mean().iloc[-1]
    ma20 = closes.rolling(20).mean().iloc[-1]
    ma60 = closes.rolling(60).mean().iloc[-1] if len(closes) >= 60 else None
    
    # RSI(14)：通达信口径 Wilder 平滑（SMA(...,N,1)），非算术平均
    # 公式：WRSI:=SMA(MAX(CLOSE-LC,0),N,1)/SMA(ABS(CLOSE-LC),N,1)*100
    delta = closes.diff()
    gain = delta.clip(lower=0)
    loss = (-delta.clip(upper=0))
    avg_gain = _wilder_series(gain).iloc[-1]
    avg_loss = _wilder_series(loss).iloc[-1]
    if avg_loss == 0:
        rsi = 100.0 if avg_gain > 0 else 50.0
    else:
        rsi = 100 - (100 / (1 + avg_gain / avg_loss))
    
    # MACD(12,26,9)：通达信口径，EMA 以前 N 项均值做种子
    # 公式：DIFF:=EMA(CLOSE,12)-EMA(CLOSE,26); DEA:=EMA(DIFF,9); MACD:=2*(DIFF-DEA)
    ema12 = _tdx_ema(closes, 12)
    ema26 = _tdx_ema(closes, 26)
    dif = ema12 - ema26
    dea = _tdx_ema(dif, 9)
    macd = (dif - dea) * 2
    
    macd_hist = macd.iloc[-1]
    macd_dif = dif.iloc[-1]
    macd_dea = dea.iloc[-1]
    macd_signal = "金叉" if macd_hist > 0 else "死叉"
    
    # 布林带(20,2)
    bb_middle = closes.rolling(20).mean()
    bb_std = closes.rolling(20).std()
    bb_upper = bb_middle + 2 * bb_std
    bb_lower = bb_middle - 2 * bb_std
    
    bb_pos = (closes.iloc[-1] - bb_lower.iloc[-1]) / (bb_upper.iloc[-1] - bb_lower.iloc[-1]) * 100 if bb_upper.iloc[-1] != bb_lower.iloc[-1] else 50
    bb_signal = "超买" if bb_pos > 80 else ("超卖" if bb_pos < 20 else "正常")
    
    # 近期涨跌
    # 插针形态（长影线+短实体），与 technical_indicators 判定口径一致
    pins = detect_pins(df)
    pin_labels = {"lower": "长下影(偏多)", "upper": "长上影(偏空)"}
    pin_text = "、".join(pin_labels[k] for k in dict.fromkeys(pins)) if pins else "无"
    recent_return = (closes.iloc[-1] / closes.iloc[-5] - 1) * 100 if len(closes) >= 5 else 0
    
    return {
        "收盘价": closes.iloc[-1],
        "MA5": round(ma5, 2),
        "MA20": round(ma20, 2),
        "MA60": round(ma60, 2) if ma60 else None,
        "RSI": round(rsi, 1),
        "MACD直方图": round(macd_hist, 4),
        "MACD_DIF": round(macd_dif, 4),
        "MACD_DEA": round(macd_dea, 4),
        "MACD信号": macd_signal,
        "布林带位置%": round(bb_pos, 1),
        "布林带信号": bb_signal,
        "5日涨跌%": round(recent_return, 2),
        "插针": pin_text,
        "最新日期": df["日期"].iloc[-1] if "日期" in df.columns else None
    }
